        for i in target.ancestors.indices {
            let fd = try open {
                i == 0 ? Darwin.open(target.ancestors[i].url.path, flags) :
                    Darwin.openat(ancestorFDs[i - 1], target.ancestors[i].url.lastPathComponent, flags)
