        try attempt.requireClosingResource(ancestorFDs[i])
        if i > 0 { try attempt.requireClosingResource(ancestorFDs[i - 1]) }
        try attempt.freshBinding()
        var held = stat(), named = stat()
        let heldResult = Darwin.fstat(ancestorFDs[i], &held)
