            guard let parent = ancestorFDs.last,
                  Darwin.fstatat(parent, target.url.lastPathComponent, &named, AT_SYMLINK_NOFOLLOW) == 0 else {
                throw ProtectedFilePolicyError.identityChanged
            }
            try attempt.freshBinding()
