    func requireCompletedWork() throws {
        guard readBytes == expectedBytes, readCalls <= expectedCalls,
              completedReadPasses == 2 else {
            throw ProtectedFilePolicyError.identityChanged
        }
        _ = try requirePolicyBoundary()
