        let mode: Mode
        let kind: OwnedFileKindV1
        let url: URL, rootURL: URL
        let parentDescriptor: Int32, selectedName: String, borrowedDescriptor: Int32
        let expectedFact: EraseColdControlLeafFactV1, expectedFlags: UInt32
